<?php
require_once 'koneksi.php';function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$nomor=(int)($_GET['nomor']??0);$order=null;$estimasi=null;
if($nomor>0){$stmt=$conn->prepare("SELECT nomor_antrian,status,created_at FROM pesanan WHERE DATE(created_at)=CURDATE() AND nomor_antrian=? ORDER BY id DESC LIMIT 1");$stmt->bind_param('i',$nomor);$stmt->execute();$order=$stmt->get_result()->fetch_assoc();$stmt->close();if($order && $order['status']==='menunggu'){$stmt=$conn->prepare("SELECT COUNT(*) jumlah FROM pesanan WHERE DATE(created_at)=CURDATE() AND status='menunggu' AND nomor_antrian<?");$stmt->bind_param('i',$nomor);$stmt->execute();$ahead=(int)$stmt->get_result()->fetch_assoc()['jumlah'];$estimasi=max(1,($ahead+1)*5);$stmt->close();}}
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cek Pesanan</title><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><div class="topbar-inner"><a class="brand" href="display.php"><span class="brand-mark">K</span><span>Kantin<span class="brand-light">Sekolah</span></span></a><nav class="nav"><a href="display.php">Display Antrean</a><a href="index.php">Kasir</a></nav></div></header><main class="page"><section class="page-heading"><div><p class="eyebrow">STATUS PESANAN</p><h1>Cek Pesanan</h1><p class="muted">Lihat perkembangan pesanan berdasarkan nomor antrean.</p></div></section><section class="panel" style="padding:24px;max-width:560px"><form method="get" style="display:flex;gap:10px;flex-wrap:wrap"><input type="number" name="nomor" min="1" value="<?= $nomor?:'' ?>" placeholder="Nomor antrean" required><button class="button button-primary">Periksa</button></form><?php if($nomor):if(!$order): ?><p class="alert alert-error">Nomor antrean tidak ditemukan untuk hari ini.</p><?php else: ?><div style="text-align:center;padding:20px"><p class="queue-label">NOMOR ANTREAN</p><h1>#<?= (int)$order['nomor_antrian'] ?></h1><span class="status status-<?= e($order['status']) ?>"><?= e(ucfirst($order['status'])) ?></span><p><?= $order['status']==='menunggu'?'Perkiraan waktu tunggu: sekitar '.$estimasi.' menit':($order['status']==='diproses'?'Pesanan sedang dibuat.':($order['status']==='siap'?'Pesanan siap diambil.':'Pesanan telah diambil.')) ?></p></div><?php endif;endif; ?></section></main></body></html>